<script>
 import {onMount} from 'svelte';
 import {HELLO_CAPTURE_SECONDS,helloBlobName,validHelloBlobName,helloUsage,helloCaptureRows,helloSavePlan,helloCapabilitiesText} from './NfqwsClientHelloModel.js';
 let {active=false,serviceBusy=false,onRequest=async()=>{},onNotice=()=>{},onSaved=()=>{}}=$props();
 let capabilities=$state(null),capError=$state(''),capLoaded=$state(false),capLoading=$state(false),capAttempted=$state(false);
 let deviceIP=$state(''),deviceInterface=$state(''),capturePhase=$state('IDLE'),captureError=$state(''),captureData=$state(null),candidates=$state([]),captured=$state(null);
 let sni=$state(''),blobName=$state(''),phase=$state('IDLE'),generated=$state(null),resultLabel=$state(''),error=$state(''),working=$state(false);
 let alive=false,epoch=0,abort=null;
 const usage=$derived(helloUsage(generated,blobName,sni,capabilities));
 const locked=$derived(serviceBusy||working||capLoading);
 function notify(text,type=''){onNotice({text,type});}
 function cancel(){epoch++;abort?.abort();abort=null;working=false;capLoading=false;}
 function invalidateGenerated(){generated=null;if(phase==='VALID'||phase==='СОХРАНЕНО')phase='IDLE';}
 async function loadCapabilities(){if(!alive||!active||capLoading)return;const seq=++epoch,c=new AbortController();abort?.abort();abort=c;capLoading=true;capAttempted=true;capError='';try{const data=await onRequest('/clienthello/capabilities',{method:'GET',signal:c.signal});if(!alive||seq!==epoch||c.signal.aborted)return;capabilities=data;capLoaded=true;}catch(e){if(alive&&seq===epoch&&!c.signal.aborted){capError=String(e?.message||e);capLoaded=false;}}finally{if(abort===c)abort=null;if(alive&&seq===epoch)capLoading=false;}}
 async function capture(){if(!alive||!active||locked||!capabilities?.tcpdump_available)return;const seq=++epoch,c=new AbortController();abort?.abort();abort=c;working=true;capturePhase='CAPTURING';captureError='';captureData=null;candidates=[];captured=null;invalidateGenerated();
 try{const d=await onRequest('/clienthello/capture',{method:'POST',signal:c.signal,body:JSON.stringify({device_ip:deviceIP.trim(),interface:deviceInterface.trim(),seconds:HELLO_CAPTURE_SECONDS})});if(!alive||seq!==epoch||c.signal.aborted)return;captureData=d;candidates=helloCaptureRows(d);capturePhase=`${candidates.length} FOUND`;}catch(e){if(alive&&seq===epoch&&!c.signal.aborted){capturePhase='ОШИБКА';captureError=String(e?.message||e);}}finally{if(abort===c)abort=null;if(alive&&seq===epoch)working=false;}}
 function selectCapture(item){if(!item?.valid||locked)return;captured=item;generated=null;phase='CAPTURED';error='';if(!sni.trim())sni='www.google.com';blobName=helloBlobName(item.sni||'captured',true);}
 async function create(method){if(!alive||!active||locked)return;const host=sni.trim();if(!host){error='Укажи SNI';return;}if(method==='forge'&&(!captured?.valid||typeof captured.content_base64!=='string')){error='Нет действительного захваченного ClientHello';return;}
 const seq=++epoch,c=new AbortController();abort?.abort();abort=c;working=true;phase=method==='forge'?'FORGING':'RUNNING';error='';generated=null;
 try{const body=method==='forge'?{content_base64:captured.content_base64,sni:host}:null;const result=method==='forge'?await onRequest('/clienthello/forge',{method:'POST',signal:c.signal,body:JSON.stringify(body)}):await onRequest('/clienthello/generate?sni='+encodeURIComponent(host),{method:'GET',signal:c.signal});if(!alive||seq!==epoch||c.signal.aborted)return;generated=result;phase=result?.valid?'VALID':'INVALID';resultLabel=method==='forge'?`Клон ${result?.source_sni||'captured'} →`:'Синтетический ClientHello';if(!blobName.trim())blobName=helloBlobName(result?.sni||host);}
 catch(e){if(alive&&seq===epoch&&!c.signal.aborted){phase='ОШИБКА';error=String(e?.message||e);}}finally{if(abort===c)abort=null;if(alive&&seq===epoch)working=false;}}
 async function saveBlob(){if(!alive||!active||locked||!generated?.valid)return;const seq=++epoch,c=new AbortController();abort?.abort();abort=c;working=true;phase='ПРОВЕРКА INVENTORY';error='';
 try{const inventory=await onRequest('/blobs',{method:'GET',signal:c.signal});if(!alive||seq!==epoch||c.signal.aborted)return;const plan=helloSavePlan(generated,blobName,inventory?.files);if(!globalThis.confirm(`${plan.replace?'Заменить':'Сохранить'} ${plan.name}? ${plan.replace?'Будет создан safety backup. ':''}nfqws2.conf и runtime не изменятся.`)){phase='VALID';return;}
 phase='СОХРАНЕНИЕ';await onRequest('/blobs/install',{method:'POST',signal:c.signal,body:JSON.stringify(plan)});if(!alive||seq!==epoch||c.signal.aborted)return;phase='СОХРАНЕНО';onSaved();notify(`${plan.name}: ClientHello blob сохранён. Runtime не изменён.`,'good');
 }catch(e){if(alive&&seq===epoch&&!c.signal.aborted){phase='ОШИБКА';error=String(e?.message||e);notify(`ClientHello save: ${error}`,'error');}}finally{if(abort===c)abort=null;if(alive&&seq===epoch)working=false;}}
 onMount(()=>{alive=true;return()=>{alive=false;cancel();};});
 $effect(()=>{if(active&&!capAttempted&&!capLoading&&alive)void loadCapabilities();});
 $effect(()=>{if(!active&&(working||capLoading)){cancel();capAttempted=false;}});
</script>
<div class="blob-shell" data-svelte-owned="nfqws-clienthello">
 <article class="panel clienthello-lab"><div class="panel-head"><div><h2>ClientHello Forge</h2><div class="section-kicker">Поймать настоящий ClientHello → заменить SNI → получить blob для nfqws2</div></div><span id="clientHelloState" class="config-badge">{phase}</span></div>
 <div class="setup-note"><b>Основной режим:</b> RouterForge берёт настоящий ClientHello выбранного устройства и меняет только SNI; остальной TLS fingerprint сохраняется.</div><div id="clientHelloCapabilitiesDetail" class="setup-note" style="margin-top:8px">{helloCapabilitiesText(capabilities)}{#if capError}<div class="notice error">{capError}</div>{/if} <button disabled={locked} onclick={loadCapabilities}>Обновить возможности</button></div>
 <div class="clienthello-capture"><div class="panel-head"><div><h2>1. Поймать ClientHello устройства</h2><div class="section-kicker">Во время захвата открой новый HTTPS-сайт на устройстве</div></div><span id="clientHelloCaptureState" class="config-badge">{capturePhase}</span></div>
 <div class="clienthello-grid"><label class="v2-label">IP устройства<input id="clientHelloDeviceIP" class="search mono" placeholder="192.168.1.50" bind:value={deviceIP} disabled={locked}></label><label class="v2-label">Интерфейс<input id="clientHelloInterface" class="search mono" placeholder="пусто = br0 / auto" bind:value={deviceInterface} disabled={locked}></label></div><div class="toolbar"><button id="clientHelloCapture" class="primary" disabled={locked||!capabilities?.tcpdump_available} onclick={capture}>Снять 5 секунд</button></div>
 <div id="clientHelloCaptureResult" class="clienthello-candidates">{#each candidates as item,i (i)}<div class="clienthello-candidate"><div><strong>{item.sni||'ClientHello без SNI'}</strong><span>{item.src_ip||''} → {item.dst_ip||''}:{Number(item.dst_port||0)} · {Number(item.size||0)} bytes · {item.detail||''}</span></div><button disabled={!item.valid||locked} onclick={()=>selectCapture(item)}>Использовать как основу</button></div>{:else}<div class="empty">{captureError||captureData?.hint||'Capture ещё не запускался.'}</div>{/each}</div></div>
 <div style="margin-top:14px"><div class="panel-head"><div><h2>2. Создать blob</h2><div class="section-kicker">SNI внутри fake ClientHello</div></div><span id="clientHelloCloneCapability" class="config-badge">{capabilities?.dynamic_clone_available?'CLONE: ЕСТЬ':'STATIC BLOB'}</span></div>
 <div class="clienthello-grid"><label class="v2-label">Новый SNI<input id="clientHelloSNI" class="search" placeholder="www.google.com" bind:value={sni} oninput={invalidateGenerated} disabled={locked}></label><label class="v2-label">Имя blob<input id="clientHelloName" class="search mono" placeholder="tls_clienthello_www_google_com.bin" bind:value={blobName} disabled={locked}></label></div>
 <div class="toolbar"><button id="clientHelloForge" class="primary" disabled={locked||!captured?.valid} onclick={()=>create('forge')}>Создать из захваченного</button><button id="clientHelloGenerate" disabled={locked||!sni.trim()} onclick={()=>create('generate')}>Синтетический fallback</button><button id="clientHelloSave" disabled={locked||!generated?.valid||!validHelloBlobName(blobName)} onclick={saveBlob}>Сохранить blob</button></div>
 <div id="clientHelloResult" class="clienthello-result">{#if generated}<div class:good={generated.valid} class:bad={!generated.valid} class="diagnostic"><div class="diagnostic-icon">{generated.valid?'✓':'!'}</div><div><div class="diagnostic-title">{resultLabel} · {generated.sni||'no SNI'}</div><div class="diagnostic-detail">{generated.detail||''} · {Number(generated.size||0)} bytes · sha256 {String(generated.sha256||'').slice(0,20)}…</div></div></div>{:else if captured}<div class="diagnostic good"><div class="diagnostic-icon">✓</div><div><div class="diagnostic-title">Основа: {captured.sni||'ClientHello без SNI'}</div><div class="diagnostic-detail">{Number(captured.size||0)} bytes · порт {Number(captured.dst_port||0)}</div></div></div>{:else}<div class="empty">Сначала поймай ClientHello устройства или используй синтетический fallback.</div>{/if}{#if error}<div class="notice error" role="alert">{error}</div>{/if}</div>
 <pre id="clientHelloUsage" class="v2-args" style="margin-top:10px;white-space:pre-wrap">{usage}</pre></div></article>
 <div class="blob-note">Сохранение пишет только .bin через Blob Manager. Конфиг nfqws2.conf и runtime автоматически не меняются.</div>
</div>
